using NeutronStar.WinUINative.Models;
static void Check(bool value,string label){if(!value)throw new Exception(label);}
var clock=new Clock();using var model=new MainModel(clock);model.Start(true);Check(clock.Count==0,"not ready");model.Ready();model.Start(true);clock.Advance(1000);Check(model.Progress==50,"progress");model.Cancel();Check(model.Status=="Simulation canceled."&&clock.Count==0,"cancel");model.Reset();model.Start(false);clock.Advance(2000);Check(model.Progress==100&&!model.Running&&clock.Count==0,"complete");model.Open();var list=model.Workbench;Check(list.Rows[0].Id==0,"initial");list.Replace(10000);Check(list.Rows[0].Id==1000,"10k");list.Replace(1000);list.Reverse();Check(list.Rows[0].Id==11999,"reverse");list.Splice();Check(list.Rows[0].Id==12000,"splice");var old=list.Rows[0];list.Update();Check(list.Tick==1&&old.Value==0&&list.Rows[0].Value==1,"immutable update");list.Query="row-12000 ";Check(list.Rows.Count==1,"filter");list.Query="missing";Check(list.Rows.Count==0,"empty");list.Query="";foreach(var hz in new[]{10,30,60}){list.Burst(hz);clock.Advance(100);list.Stop();Check(clock.Count==0,"stop");}list.Remount();Check(list.Tick==0&&list.Rows[0].Id==0,"remount");list.Burst(30);model.Back();Check(clock.Count==0,"leave");model.Open();Check(model.Workbench.Tick==0&&model.Workbench.Rows[0].Id==0,"reopen");model.Dispose();Check(clock.Count==0&&!model.EncryptCommand.CanExecute(null),"dispose");Console.WriteLine("PASS independent WinUI MVVM workflow/list/timer assertions");
sealed class Clock:IClock{private double now;private int serial;private readonly Dictionary<int,Action> tasks=new();public double Now=>now;public int Count=>tasks.Count;public IDisposable Repeat(Action callback,double periodMs){int id=++serial;tasks[id]=callback;return new Lease(()=>tasks.Remove(id));}public void Advance(double ms){now+=ms;foreach(var callback in tasks.Values.ToArray())callback();}private sealed class Lease(Action stop):IDisposable{public void Dispose()=>stop();}}
